import java.math.BigInteger

fun main() {
    val x = readLine()!!.trim().toBigInteger()
    val bi360 = BigInteger.valueOf(360)
    var r = (x.negate()).mod(bi360)
    // r is now non-negative in [0,360)
    var bestK = 0
    var bestDev = BigInteger.valueOf(-1)
    for (k in 0..3) {
        val total = (r.add(BigInteger.valueOf(90L * k))).mod(bi360)
        val dev = if (total > bi360.subtract(total)) bi360.subtract(total) else total
        if (bestDev == BigInteger.valueOf(-1) || dev < bestDev) {
            bestDev = dev
            bestK = k
        }
    }
    println(bestK)
}
